window.products.push({"id":1162183,"name":"My Shower T Shower/Tub Splash Guard","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81Hfx0-miQL._AC_SL1500_.jpg","description":"My Shower T Shower/Tub Splash Guard is a shower/tub splash guard that keeps the water in your shower. It is removable, constructed of high grade plastics and made in the USA. It eliminates wet bathroom floors. Our patent pending design keeps your shower curtain flush against the shower wall which prevents water from escaping or leaking outside. No tools, caulk or messy adhesives required. Unlike other splash guards, My Shower T Shower/Tub Splash Guard is not a trip hazard. Do not settle with other splash guards that comprise you bathroom decor. My Shower T's clear design blends into any bathroom and CLEARLY gets the job done!","images":["https://m.media-amazon.com/images/I/81Hfx0-miQL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"My Shower T","source_asin":"B01BOG3SZW","category_path":"Home & Kitchen"},"sku":"BM-1162183","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01BOG3SZW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01BOG3SZW","price_pending":true,"merchant_ready":false});
